"""Vector equation widget: the SVGs generated by ``tools/render_equations.py``, recoloured from the theme.

Used by Analysis (Model details, Help); formerly part of the Calculation details panel.
"""

from __future__ import annotations

from pathlib import Path

from PySide6.QtCore import QByteArray, QRectF, QSize
from PySide6.QtGui import QPainter
from PySide6.QtSvg import QSvgRenderer
from PySide6.QtWidgets import QSizePolicy, QWidget

from ..theme import THEME, t

EQ_DIR = Path(__file__).resolve().parents[1] / "equations"

_SVG_SRC: dict[str, str] = {}


def _svg_source(key: str) -> str:
    """Read an equation SVG once.  The files never change, only the recolouring does, and a
    theme switch was re-reading 104 of them from disk each time."""
    src = _SVG_SRC.get(key)
    if src is None:
        path = EQ_DIR / f"{key}.svg"
        src = path.read_text(encoding="utf-8") if path.exists() else ""
        _SVG_SRC[key] = src
    return src


class Equation(QWidget):
    """Vector equation (SVG generated by tools/render_equations.py), recoloured to text-primary."""

    def __init__(self, key: str, scale: float = 1.0, parent=None):
        super().__init__(parent)
        self.key = key
        self._src = _svg_source(key)
        self._renderer = None
        self.scale = scale
        self._load()
        THEME.changed.connect(self._theme_changed)

    def _theme_changed(self, *_):
        self._load()
        self.update()

    def _load(self):
        if not self._src:
            return
        data = self._src.replace("currentColor", t("text-primary"))
        self._renderer = QSvgRenderer(QByteArray(data.encode("utf-8")))
        s = self._renderer.defaultSize()
        # Natural size is the design size; a narrower Details panel (Windows 125 % / 150 %) may
        # give it less width, and the vector equation is then drawn smaller rather than clipped.
        self.natural = QSize(int(s.width() * self.scale * 1.1), int(s.height() * self.scale * 1.1))
        self.setFixedHeight(self.natural.height())
        self.setMinimumWidth(min(self.natural.width(), 120))
        self.setMaximumWidth(self.natural.width())
        self.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Fixed)

    def sizeHint(self) -> QSize:
        return getattr(self, "natural", QSize(0, 0))

    def paintEvent(self, _e):
        if self._renderer:
            p = QPainter(self)
            p.setRenderHint(QPainter.RenderHint.Antialiasing)
            k = min(1.0, self.width() / max(1, self.natural.width()))
            w, h = self.natural.width() * k, self.natural.height() * k
            self._renderer.render(p, QRectF(0, (self.height() - h) / 2, w, h))
            p.end()
